const int N=1;
const int HIT_PERCENT = 100; 

const int TAG_READ_CYCLES      = 0;
const int TAG_WRITE_CYCLES     = 1;
const int DATA_READ_CYCLES     = 1;
const int DATA_WRITE_CYCLES    = 1;
const int META_RESP_CYCLES     = 0;
const int PROBE_OVERHEAD_CYCLES= 0;
const int LAT_MIN = 40;
const int LAT_MAX = 200;

clock time_esti = 0;
clock final_est = 0;

int total_cycles = 0;

/* --------- Request / metadata booleans (shared globals) --------- */
bool read[N] ;
bool write[N] ;
bool probe_request[N] ;
bool prefetch_receive[N] ;
bool fill[N] ;

bool hit[N] ;
bool miss[N] ;
bool hitNoPermission[N] ;

bool write_allocate[N] ;
bool write_required[N] ;

/* --------- queues / issueQ flags unchanged --------- */
bool issueQ_data_read[N] ;
bool issueQ_data_write[N] ;
bool issueQ_tag_write[N] ;
bool issueQ_metadata_response[N] ;
bool send_queue[N] ;

int enqueue_tag_owner;
int enqueue_data_read_owner;
int enqueue_data_write_owner;
int enqueue_tag_write_owner;

/* Verifying properties */
int left_idle[N];
clock time = 0;
int clock_cycle_time_elapsed;

/* Number of requests generated till now. */
int generated = 0;
int next_id = 0;

int cache_line_state[N];

/* helper */
bool in_issueQ(bool q) { return q; }

/* Channels (same as your model) */
broadcast chan req_ready[N], gen_req_type[N], Read_Req[N], Write_Req[N], Protocol_Ack[N];
broadcast chan Req_Gen[N], done[N];

int rng_seed = 1234; // must be a constant within [-32768, 32767]

int next_rand(int n) {
    rng_seed = (37 * rng_seed + 11) % 10007; // small primes within safe bounds
    return rng_seed % n;
}

int cycles[N];
int req_lat[N];
bool req_active[N];
int last_latency[N];
int checking_cycles[N];
int time_taken_lat;

int total_latency;
int completed;
int req_completed;


/* IMPORTANT: init_values no longer sets request booleans  */
void init_values(int i) {

 read[i] = false;
 write[i] = false;
 probe_request[i] = false;
 prefetch_receive[i] = false;
 fill[i] = false;

 hitNoPermission[i] = false;

 write_allocate[i] = false;
 write_required[i] = false;
    issueQ_data_read[i] = false;
    issueQ_data_write[i] = false;
    issueQ_tag_write[i] = false;
    issueQ_metadata_response[i] = false;
    send_queue[i] = false;
}

void update_hit_miss(int i) {
    hit[i] = cache_line_state[i]==1 || cache_line_state[i]==2;
    miss[i] = cache_line_state[i]==0;
}

/* Existing helper predicates (XML escaped) */
bool idle_read_conditions(int i){
    return (read[i] && (hit[i] || miss[i])) || (write[i] && (miss[i] && write_allocate[i])) || (probe_request[i] && hit[i]) || (prefetch_receive[i] && miss[i]);
}

bool idle_write_conditions(int i){
    return (write[i] && hit[i] && write_required[i]) || (fill[i] && hit[i]);
}

bool idle_tag_write_done(int i){ 
    return hitNoPermission[i] || (write[i] && hit[i] && !write_required[i]) || (write[i] && miss[i] && !write_allocate[i]);
}

bool write_idle_to_tag_rd_done(int i) {
    return idle_write_conditions(i) && !idle_read_conditions(i) && !idle_tag_write_done(i);
}

bool read_idle_to_tag_rd_done(int i) {
    return idle_read_conditions(i) && !idle_write_conditions(i) && !idle_tag_write_done(i);
}

bool idle_to_tag_wr_done(int i) {
    return idle_tag_write_done(i) && !idle_read_conditions(i) && !idle_write_conditions(i);
}

void set_data_read(int i) {
    //left_idle[i]=1;
    //issueQ_data_read[i] = true;
    issueQ_data_read[i] = true;
    issueQ_data_write[i] = false;
}

void set_data_write(int i) {
     //left_idle[i]=1;
     //issueQ_data_write[i] = true;
     issueQ_data_write[i] = true;
     issueQ_data_read[i] = false;
}

void set_meta_dataQ(int i){
    left_idle[i]=1;
    issueQ_metadata_response[i] = true;
}

bool valid_idle_condition(int i) {
    return ((read[i] && (hit[i] || miss[i])) || (write[i] && (miss[i] && write_allocate[i])) || (probe_request[i] && hit[i]) || (prefetch_receive[i] && miss[i]))
         || ((write[i] && hit[i] && write_required[i]) || (fill[i] && hit[i]))
         || (hitNoPermission[i] || (write[i] && hit[i] && !write_required[i]) || (write[i] && miss[i] && !write_allocate[i]));
}

int temp[N];

// -----------------------------------------------------------------------------------------------------------------------------------------------------------------

int global_cycle = 0;

int start_cycle[N];
int end_cycle[N];
int latency_cycles[N];

bool measuring = false;

broadcast chan tick;
//------------------------------------------------------------------------------------------------------------------------------------------------------------------

bool tag_read_done[N];
bool tag_write_done[N];
bool data_read_done[N];
bool data_write_done[N];

