const int REQ_NONE      = -1;
const int REQ_READ      = 1;
const int REQ_WRITE     = 2;
const int REQ_FILL      = 3;
const int REQ_PREFETCH  = 4;
const int REQ_PROBE     = 5;

bool enqueue_tag_flag = false;
int  enqueue_tag_id = REQ_NONE;

bool enqueue_data_read_flag = false;
int  enqueue_data_read_id = REQ_NONE;

bool enqueue_data_write_flag = false;
int  enqueue_data_write_id = REQ_NONE;

bool enqueue_tag_write_flag = false;
int  enqueue_tag_write_id = REQ_NONE;

/* ------------------Current Request--------------------- */
int req_id;
int req_valid[N];
int req_type[N]; 
int req_target_line[N]; 

const int QUEUE_CAP = N;

// --- Queue ring buffers (capacity N) ---
int q_tag_read[N]; int tag_head = 0; int tag_tail = 0; int tag_count = 0;
int q_data_read[N]; int dr_head = 0;    int dr_tail = 0;    int dr_count = 0;
int q_data_write[N]; int dw_head = 0;   int dw_tail = 0;    int dw_count = 0;
int q_tag_write[N]; int tw_head = 0;    int tw_tail = 0;    int tw_count = 0;

// --- temporary variables for enqueue/dequeue handshakes ---
int enqueue_req_id = REQ_NONE;   // generator sets then signals enqueue
int dequeue_req_id = REQ_NONE;   // manager sets then signals worker

// --- Channels (broadcast so many workers can listen) ---
//chan enqueue_tag_req, enqueue_data_read_req, enqueue_data_write_req, enqueue_tag_write_req;
broadcast chan tag_available, data_read_available, data_write_available, tag_write_available;

//---------------Queue Manager Helper Functions--------------------------------

int request_stage[N]; 
const int STAGE_IDLE = 0;
const int STAGE_TAG_READ = 1;
const int STAGE_DATA_RW = 2;
const int STAGE_TAG_WRITE = 3;
const int STAGE_COMPLETE = 4;

bool qm_busy = false;
void deque(){
    if(tag_count>0) {
        dequeue_req_id = q_tag_read[tag_head];
        tag_head = (tag_head + 1) % N;
        tag_count = tag_count - 1;
        // Don't change stage here - worker will handle it
        qm_busy = false;
    } else {
        dequeue_req_id = REQ_NONE;
        qm_busy = false;
    }
    qm_busy = false;
}
void enque() {
    if(tag_count < QUEUE_CAP && enqueue_tag_id != REQ_NONE) {
        q_tag_read[tag_tail] = enqueue_tag_id;
        tag_tail = (tag_tail + 1) % N;
        tag_count = tag_count + 1;
        request_stage[enqueue_tag_id] = STAGE_TAG_READ;  // Mark as in tag_read stage
        enqueue_tag_id = REQ_NONE;
        qm_busy = false;

  //      enqueue_tag_flag = false;
  //      enqueue_tag_id = REQ_NONE;
    //    enqueue_tag_owner = REQ_NONE;
    } else {
        // Handle overflow or invalid request
        enqueue_tag_id = REQ_NONE;
        qm_busy = false;
    }
    qm_busy = false;
}

void data_read_enq() {
    if(dr_count < QUEUE_CAP && enqueue_data_read_id != REQ_NONE) {
        q_data_read[dr_tail] = enqueue_data_read_id;
        dr_tail = (dr_tail+1)%N;
        dr_count++;
        request_stage[enqueue_data_read_id] = STAGE_DATA_RW;  // Add this
        enqueue_data_read_id = REQ_NONE;

   //     enqueue_data_read_flag = false;
   //     enqueue_data_read_id = REQ_NONE;
   //     enqueue_data_read_owner = REQ_NONE;
    }
    qm_busy = false;

}

void data_write_enq() {
    if(dw_count < QUEUE_CAP && enqueue_data_write_id != REQ_NONE) {
        q_data_write[dw_tail] = enqueue_data_write_id;
        dw_tail = (dw_tail+1)%N;
        dw_count++;
        request_stage[enqueue_data_write_id] = STAGE_DATA_RW;  // Add this
        enqueue_data_write_id = REQ_NONE;
        qm_busy = false;

    //    enqueue_data_write_flag = false;
    //    enqueue_data_write_id = REQ_NONE;
    //    enqueue_data_write_owner = REQ_NONE;
    }
    qm_busy = false;
}

void tag_write_enq() {
    if(tw_count < QUEUE_CAP && enqueue_tag_write_id != REQ_NONE) {
        q_tag_write[tw_tail] = enqueue_tag_write_id;
        tw_tail = (tw_tail+1)%N;
        tw_count++;
        request_stage[enqueue_tag_write_id] = STAGE_TAG_WRITE;  // Add this
        enqueue_tag_write_id = REQ_NONE;
        qm_busy = false;

    //    enqueue_tag_write_flag = false;
    //    enqueue_tag_write_id = REQ_NONE;
    //    enqueue_tag_write_owner = REQ_NONE;
    }
    qm_busy = false;
}

// Add busy flags for workers (to prevent double assignment)
bool tag_worker_busy = false;
bool data_read_worker_busy = false;
bool data_write_worker_busy = false;
bool tag_write_worker_busy = false;

// Helper function to check if pipeline slot is available
bool can_advance_to_stage(int req_id, int target_stage) {
    if(target_stage == STAGE_TAG_READ) {
        return !tag_worker_busy && tag_count < QUEUE_CAP;
    } else if(target_stage == STAGE_DATA_RW) {
        if(read_idle_to_tag_rd_done(req_id)) {
            return !data_read_worker_busy && dr_count < QUEUE_CAP;
        } else {
            return !data_write_worker_busy && dw_count < QUEUE_CAP;
        }
    } else if(target_stage == STAGE_TAG_WRITE) {
        return !tag_write_worker_busy && tw_count < QUEUE_CAP;
    }
    return false;
}

void data_read_deq() {
    if(dr_count > 0) {
        dequeue_req_id = q_data_read[dr_head];
        dr_head = (dr_head+1)%N;
        dr_count--;
        qm_busy = false;
    }
    qm_busy = false;
}

void data_write_deq() {
    if(dw_count > 0) {
        dequeue_req_id = q_data_write[dw_head];
        dw_head = (dw_head+1)%N;
        dw_count--;
        qm_busy = false;
    }
    qm_busy = false;
}

void tag_write_deq() {
    if(tw_count > 0) {
        dequeue_req_id = q_tag_write[tw_head];
        tw_head = (tw_head+1)%N;
        tw_count--;
        qm_busy = false;
    }
    qm_busy = false;
}

//----------------------------------------------------------------------------------------
//----------------------------------------------------------------------------------------
// Distribution mode selectors
const int DIST_UNIFORM = 0;
const int DIST_POISSON = 1;
const int DIST_WEIGHTED = 2;
const int DIST_GAUSSIAN = 3;

int r;
int g;

// User selects these at the top
const int arrival_distribution = DIST_POISSON;
const int type_distribution    = DIST_UNIFORM;

int pick_arrival_time() {
    if (arrival_distribution == DIST_POISSON) {
        // Poisson arrival → exponential waiting
        // Return is ignored; UPPAAL uses exponentialrate
        return -1; 
    }

    if (arrival_distribution == DIST_UNIFORM) {        
        return next_rand(10) + 1;  // uniform delay 1–10
    }

    if (arrival_distribution == DIST_GAUSSIAN) {
        // Gaussian approximation by sum of uniforms
        return (next_rand(5) + next_rand(5) + 1);
    }

    // Default deterministic arrival
    return 5;
}

int pick_request_type() {
    if (type_distribution == DIST_UNIFORM) {
        return next_rand(5) + 1;     // 1..5 → your REQ_* codes
    }

    if (type_distribution == DIST_WEIGHTED) {
        int W_READ = 40;
        int W_WRITE = 20;
        int W_PROBE = 10;
        int W_FILL = 20;
        int W_PREFETCH = 10;

        int total = W_READ + W_WRITE + W_PROBE + W_FILL + W_PREFETCH;
        r = next_rand(total);

        if (r < W_READ) return REQ_READ;
        if (r < W_READ + W_WRITE) return REQ_WRITE;
        if (r < W_READ + W_WRITE + W_PROBE) return REQ_PROBE;
        if (r < W_READ + W_WRITE + W_PROBE + W_FILL) return REQ_FILL;
        return REQ_PREFETCH;
    }

    if (type_distribution == DIST_GAUSSIAN) {
        // Gaussian around middle types
        g = next_rand(3) + next_rand(3); 
        return g % 5 + 1;
    }

    return REQ_READ;  // default fallback
}
int t, rt;

//Reqeust generator calls this function
void dist_controller(int req_id) {
    // 1. Call arrival distribution (value may or may not be used)
    t = pick_arrival_time();

    // 2. Determine request type
  rt = REQ_WRITE; 

  // do {
   //     rt = fint(random_normal(2, 0.5));
   //} while (rt < 1 || rt > 5);

//Change to simulate one particular type of request -------------------------------------------------------------------------------
    req_type[req_id] = rt;

    // Clear old flags
    read[req_id] = false;
    write[req_id] = false;
    probe_request[req_id] = false;
    prefetch_receive[req_id] = false;
    fill[req_id] = false;

    // Set new ones
    read[req_id]            = (rt == REQ_READ);
    write[req_id]           = (rt == REQ_WRITE);
    probe_request[req_id]   = (rt == REQ_PROBE);
    prefetch_receive[req_id]= (rt == REQ_PREFETCH);
    fill[req_id]            = (rt == REQ_FILL);
}

