bool write_req_flag[N];
bool write_req_taken[N];
int  write_req_id[N];
//--------------------------




void init_cache_states() {
    int i;

    clock_cycle_time_elapsed = 0;
    time_taken_lat = 0;

    for(i = 0; i < N; i++) {
        checking_cycles[i] = 0;
        req_valid[i] = 0;
        req_type[i] = REQ_NONE;
        req_target_line[i] = 0;
        waiting_stage_start_tag[i]=false;
        waiting_start_data_read[i]=false;
        waiting_start_data_write[i]=false;
        waiting_start_tag_write[i]=false;
        temp[i]=-1;
        request_stage[i] = STAGE_IDLE;
        tag_write_done[i] = false;
        tag_read_done[i] = false;
        data_read_done[i] = false;
        data_write_done[i] = false;

        stage_start_tag_req[i] = false;
        stage_start_tag_taken[i] = false;
        stage_start_tag_id[i] = REQ_NONE;

        stage_start_data_read_req[i] = false;
        stage_start_data_read_taken[i] = false;
        stage_start_data_read_id[i] = REQ_NONE;

        stage_start_data_write_req[i] = false;
        stage_start_data_write_taken[i] = false;
        stage_start_data_write_id[i] = REQ_NONE;

        stage_start_tag_write_req[i] = false;
        stage_start_tag_write_taken[i] = false;
        stage_start_tag_write_id[i] = REQ_NONE;

        read_req_flag[i] = false; read_req_taken[i] = false; read_req_id[i] = REQ_NONE;
        write_req_flag[i] = false; write_req_taken[i] = false; write_req_id[i] = REQ_NONE;  

        req_lat[i] = 0;
        cycles[i] = 0;
        req_active[i] = false;
        last_latency[i] = 0;

        if (next_rand(100) < HIT_PERCENT) {
            cache_line_state[i] = 1; // hit
        } else {
            cache_line_state[i] = 0; // miss
        }
    }

    dequeue_tag_req = false; dequeue_tag_taken = false; dequeue_tag_id = REQ_NONE;
    dequeue_data_read_req = false; dequeue_data_read_taken=false; dequeue_data_read_id=REQ_NONE;
    dequeue_data_write_req = false; dequeue_data_write_taken=false; dequeue_data_write_id=REQ_NONE;
    dequeue_tag_write_req = false; dequeue_tag_write_taken=false; dequeue_tag_write_id=REQ_NONE;

    enqueue_tag_flag = false; enqueue_tag_id = REQ_NONE;
    enqueue_data_read_flag = false; enqueue_data_read_id = REQ_NONE;
    enqueue_data_write_flag = false; enqueue_data_write_id = REQ_NONE;
    enqueue_tag_write_flag = false; enqueue_tag_write_id = REQ_NONE;

    enqueue_tag_owner = REQ_NONE;
    enqueue_data_read_owner = REQ_NONE;
    enqueue_data_write_owner = REQ_NONE;
    enqueue_tag_write_owner = REQ_NONE;

    total_latency=0;
    completed=0;
    req_completed=0;
}

broadcast chan req_metadata_ready;

bool tag_read_av = true;
bool data_read_av = true;
bool data_write_av = true;
bool tag_write_av = true;

int total_clock_cycles = 0;

bool any_data_read_work_available() {
    int i;
    for(i=0;i<N;i++) if(issueQ_data_read[i]) return true;
    return false;
}


void update_clocks(int id) {
    int i;
    int maxc = 0;
    for(i = 0; i < N; i++) {
        if (cycles[i] > maxc) maxc = cycles[i];
    }
    clock_cycle_time_elapsed += maxc;
    for(i = 0; i < N; i++) {
        cycles[i] = 0;
    }
}

void update_the_cycles() {
    int i;
    int maxc = 0;
    for(i = 0; i < N; i++) {
        if (checking_cycles[i] > maxc) maxc = checking_cycles[i];
    }
    time_taken_lat = time_taken_lat + maxc;
    for(i = 0; i < N; i++) {
        checking_cycles[i] = 0;
    }
}

