void move_to_next_queue(int req_id) {
        if(request_stage[req_id] == STAGE_TAG_READ) {
            // After tag_read, check what's next
            if(read_idle_to_tag_rd_done(req_id)) {
                q_data_read[dr_tail] = req_id;
                dr_tail = (dr_tail+1)%N;
                dr_count++;
            } else if(write_idle_to_tag_rd_done(req_id)) {
                q_data_write[dw_tail] = req_id;
                dw_tail = (dw_tail+1)%N;
                dw_count++;
            }
        } else if(request_stage[req_id] == STAGE_DATA_RW) {
            // After data stage, move to tag_write
            q_tag_write[tw_tail] = req_id;
            tw_tail = (tw_tail+1)%N;
            tw_count++;
        }
    }

